from lib import *
S = SS('p36')
steps = [
    step("36 个相对链接用例(base 默认是 http://a.test/dir/sub/page.html?x=1#top),Python urllib.parse.urljoin 与 Node 的 WHATWG URL(浏览器采用的标准)比较:结果相同的 25 个,不同的 11 个。相同的包括 ./、../、越过根目录的 ../../../../、/ 开头、//、只有 ?、只有 #、结尾有无斜杠、点段、javascript:、mailto: 等常规情形。", t=tl(S(1)), done=lidx(S(1), '结果相同的'), b=bars([['用例总数', 36, '36'], ['结果相同', 25, '25'], ['结果不同', 11, '11']], 36, done=[1], mark=[2]), kv=KV([['常规相对链接', 'urljoin 与浏览器一致'], ['不同的', '11 个'], ['对照对象', 'Node 的 WHATWG URL']], ['不同的'])),
    step("11 个不同的结果:空字符串(Python 保留 #top,WHATWG 去掉 fragment);前后有空格(Python 保留空格,WHATWG 去掉);反斜杠 ..\\x.html 和 \\x.html(Python 当普通字符,WHATWG 当斜杠,变成 /dir/x.html 和 /x.html);https:foo(Python 原样返回 https:foo,WHATWG 得到 https://foo/);http:///x(Python http://a.test/x,WHATWG http://x/);HTTP://C.test/Z(Python 保留主机大写,WHATWG 小写);http://a.test:80/x(Python 保留 :80,WHATWG 去掉);中文路径、中文域名、查询串里的空格(Python 原样,WHATWG 做百分号编码或 punycode)。", t=tl(S(2)), done=lidx(S(2), '中文路径', '大写 scheme', '端口'), mark=lidx(S(2), '反斜杠', '三个斜杠', '不同 scheme 的 scheme:foo', '前后有空格'), kv=KV([['urljoin', '不做编码、不转小写、不处理反斜杠'], ['WHATWG', '编码、转小写、反斜杠当斜杠'], ['影响', '同一个链接得到两种不同的字符串']], ['影响'])),
    step("urljoin 对不同 scheme 的链接原样保留,不会过滤:javascript:void(0)、mailto:a@b.test、data:text/plain,hi、tel:+123、ftp://f.test/x、file:///etc/passwd 经 urljoin 之后都原封不动,scheme 分别是 javascript、mailto、data、tel、ftp、file。爬虫必须自己检查 scheme 只放行 http 和 https,否则 file:// 之类也会进到待抓队列。", t=tl(S(3)), done=lidx(S(3), 'javascript', 'mailto'), mark=lidx(S(3), 'file:///etc/passwd', 'ftp'), kv=KV([['urljoin', '不过滤 scheme'], ['javascript / mailto / data / tel', '原样返回'], ['file:// 和 ftp://', '也原样返回,要自己过滤']], ['file:// 和 ftp://'])),
    step("<base href> 与重定向。页面 http://a.test/dir/page.html,没有 base 时 x.html 变成 /dir/x.html;有 <base href=\"http://cdn.test/assets/\"> 时三个链接都以 cdn.test 为准(x.html → /assets/x.html,/root.html → cdn.test/root.html);相对的 <base href=\"/other/\"> 也按页面所在站点解析;两个 <base> 时只有最后一个起作用(two.test)——我在 lxml 里实测的,没有查浏览器是否也取最后一个。lxml 的 make_links_absolute(url, resolve_base_href=False) 文档字符串说会忽略 <base>,实测仍然应用了:因为它调用 rewrite_links(link_repl) 时没有传这个参数,而 rewrite_links 默认 resolve_base_href=True。请求 /old 被重定向到 /new/dir/page.html 时,以请求时的 URL 当 base 得到 /next.html,以最终 URL r.url 当 base 才是 /new/dir/next.html。", t=tl(S(4)), done=lidx(S(4), '没有 <base>', '用 r.url', '<base href="/other/">'), mark=lidx(S(4), 'resolve_base_href=False', '两个 <base>', '用请求时的 URL 当 base'), kv=KV([['<base href>', '会改变所有相对链接的基准'], ['resolve_base_href=False', '实测无效(rewrite_links 默认 True)'], ['重定向后', '要用 r.url,不是请求时的 URL']], ['resolve_base_href=False'])),
]
A = mkartp('p36', 36, '爬虫,相对链接,urljoin,base标签,WHATWG,URL解析,lxml,Python,真实验证,动画演示',
    '用 Node 的 WHATWG URL 对照 Python urljoin:36 个相对链接用例有 11 个结果不同(反斜杠、前后空格、中文编码、大写主机、:80、https:foo 等);urljoin 不过滤 javascript:、file:// 等 scheme;lxml 的 make_links_absolute(resolve_base_href=False) 实测仍应用 <base>;重定向后必须用最终 URL 当 base。',
    '从页面里提取出的链接大多是相对的,爬虫要把它们变成绝对 URL 才能继续抓。看起来 urljoin 一行就行,可是浏览器遵循的 WHATWG 标准和 Python 的 RFC 风格有细节差别,<base> 标签和重定向还会改变基准。这篇用 Node 的 URL 做对照逐条看。',
    [('25 / 36', 'urljoin 与 WHATWG URL 结果相同的用例数(不同的 11 个)'), ('file://', '经 urljoin 仍原样保留的 scheme——要自己过滤,只放行 http 和 https'), ('r.url', '重定向之后解析相对链接应该用的 base(请求时的 URL 会得到错误的路径)')],
    [('常规情形一致', '<p>./、../、绝对路径、协议相对 //、只有 ? 或 #、目录结尾的斜杠、点段等 25 种用例,urljoin 与 WHATWG 的结果一致。</p>'),
     ('不一致的细节', '<p>11 个不同的结果集中在:空字符串是否保留 fragment、前后空格、反斜杠、scheme 后没有斜杠的 <code>https:foo</code>、主机大小写、默认端口、中文路径/域名/空格的编码。浏览器会修正这些写法,urljoin 不会,所以同一个链接,你的爬虫和浏览器访问的 URL 字符串可能不同。去重前最好统一一遍(上一篇)。</p>'),
     ('别的 scheme', '<p><code>urljoin</code> 对 <code>javascript:</code>、<code>mailto:</code>、<code>data:</code>、<code>tel:</code>、<code>ftp:</code>、<code>file:</code> 一律原样返回。把它们交给下载器之前必须检查 scheme。</p>'),
     ('<base> 与重定向', '<p>页面里的 <code>&lt;base href&gt;</code> 会改变所有相对链接的基准;两个 <code>&lt;base&gt;</code> 时 lxml 取最后一个。lxml 的 <code>make_links_absolute(resolve_base_href=False)</code> 在 6.1.1 里并没有忽略 <code>&lt;base&gt;</code>(源码里 <code>rewrite_links</code> 的默认参数让它仍然生效)。被重定向的页面,基准应该是最终 URL(<code>r.url</code>)而不是请求时的 URL。</p>')],
    steps,
    [ENV_P + '。Python 的 urllib.parse.urljoin(3.14.8)对照 Node v26.10.0 的 new URL(rel, base).href;lxml 6.1.1 的 make_links_absolute;重定向实验用本机服务器;lxml 的行为通过读 inspect.getsource 得到的源码确认;“两个 <base> 取最后一个”只是 lxml 的实测',
     '没有验证:真实浏览器(Chrome)对这些用例的结果(Node 的 URL 是 WHATWG 的实现,浏览器应当一致,但我没有在 Chrome 里逐条测);HTML 标准对多个 <base> 的规定;<base target> 与 xml:base;相对链接里的 IPv6、userinfo;html 属性里的 HTML 实体(&amp;)解码在不同解析器里的差异'],
    '相对链接解析')
